import json,re
from collections import defaultdict
from fractions import Fraction

def parse(expr):
 out=defaultdict(Fraction)
 for term in re.findall(r'[+-]?[^+-]+',expr.replace(' ','')):
  if not term: continue
  sign=-1 if term[0]=='-' else 1
  body=term[1:] if term[0] in '+-' else term
  if '*' in body: q,p=body.split('*',1); c=Fraction(q)
  else: p=body; c=Fraction(1)
  out[p]+=sign*c
 return {k:v for k,v in out.items() if v}
for n in (1,2,3):
 g=json.load(open(f'data/C_{n}_gamma.json'))['inhomogeneous_deformation']['gamma_structure']; s=json.load(open(f'data/C_{n}_structure.json'))
 P=s['parity']; names=s['basis']['odd']+s['basis']['even']; Kpar=0
 G=defaultdict(lambda:defaultdict(Fraction))
 for r in g:
  for p,c in parse(r['coeff']).items():G[(r['X'],r['Y'],r['Z'])][p]+=c
 failures=[]
 for (x,y,z),co in G.items():
  reverse=G[(y,x,z)]
  scale=-((-1)**(P[x]*P[y]))
  expected={p:scale*c for p,c in co.items()}
  if {k:v for k,v in reverse.items() if v}!={k:v for k,v in expected.items() if v}: failures.append(('skew',x,y,z))
  if (P.get(z,0) != (P[x]+P[y]+1)%2): failures.append(('parity',x,y,z))
 B=defaultdict(lambda:defaultdict(Fraction))
 for r in s['structure_constants']:B[(r['X'],r['Y'])][r['Z']]+=Fraction(r['coeff'])
 # gamma cyclic Jacobi, using (-1)^(px*pz) [x,[y,z]]
 for x in names:
  for y in names:
   for z in names:
    residual=defaultdict(Fraction)
    for a,b,c in ((x,y,z),(y,z,x),(z,x,y)):
     outer=(-1)**(P[a]*P[c])
     # gamma(a, [b,c]_0)
     for w,bc in B[(b,c)].items():
      for t,pc in G[(a,w)].items():
       residual[pc]+=outer*bc*pc
     # [a, kappa gamma(b,c)] = (-1)^p(a) kappa [a,gamma(b,c)]
     for (bb,cc,t), pmap in list(G.items()):
      if bb!=b or cc!=c or t=='K': continue
      for u,ac in B[(a,t)].items():
       for par,coeff in pmap.items():residual[par]+=outer*((-1)**P[a])*ac*coeff
    if any(residual.values()):
     failures.append(('jacobi',x,y,z,dict(residual))); break
   if failures and failures[-1][0]=='jacobi': break
  if failures and failures[-1][0]=='jacobi': break
 print(f'n={n}: records={len(g)}, skew/parity/jacobi failures={len(failures)}, first={failures[:1]}')
