        [
            {
                "parameter": f"gb_a1_{fermion_sign}_{column.replace('b_', 'b')}",
                "parity": 0,
            }
            for column in boson_columns
        ]
        for fermion_sign in ("p", "m")
    ]
    deformation = {
        "central_symbol": "kappa",
        "central_parity": 1,
        "parameter_parity": 0,
        "sign_convention": "gram_entry",
        "exchange_relations": [
            {
                "X": column,
                "Y": row,
                "relation": (
